// Cloudflare Worker entry: the OpenNext app for HTTP, plus the daily cron.
// The cron runs the daily job (expiry/retention in SQL, Instagram token
// refresh and media sync).

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

// The cron calls the app's own internal job route in-process (no network
// hop): maintenance in SQL, then token refresh and media sync.
async function runDaily(env: Env, ctx: Ctx): Promise<void> {
  if (!env.CRON_SECRET) throw new Error("daily job: CRON_SECRET missing");
  const req = new Request("https://worker.internal/api/jobs/daily", {
    method: "POST",
    headers: { authorization: `Bearer ${env.CRON_SECRET}` },
  });
  const res: Response = await handler.fetch(req, env, ctx);
  if (!res.ok) throw new Error(`daily job failed: HTTP ${res.status}`);
  console.log("daily job:", await res.text());
}

export default {
  fetch: handler.fetch,
  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    ctx.waitUntil(runDaily(env, ctx));
  },
};

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
